#!/bin/sh
# Build the WebAssembly core (core.c: the evaluation, the candidate list and the MCTS) into core-wasm.js (the module as base64,
# so that engine.js can load it synchronously in a worker and in Node). Then check it against the JS: node tools/check_wasm.js
# core_mt.wasm: the same core for several threads growing one MCTS tree on a shared memory (-DMT: the boards and work areas
# thread-local; shared/mtengine.js, engine.js?…&mt=1 = the lead, mt-helper.js = the helpers).
cd "$(dirname "$0")/.."
# (2026-11-11) two builds in core-wasm.js: AMZ_WASM with wasm SIMD (-msimd128), AMZ_WASM0 without it for a browser that has no
# SIMD (engine.js takes the first that compiles); the same values (tools/check_wasm.js). core_mt.wasm with SIMD only (like the other
# games' engine_mt.wasm: every browser with shared memory and threads that the page uses has it).
W="clang --target=wasm32 -nostdlib -fno-builtin -ffp-contract=off -O3 -w -Wl,--no-entry -Wl,--export-dynamic -Wl,--initial-memory=1048576"
$W -msimd128 -o /tmp/amazons-core-simd.wasm core.c || exit 1
$W -o /tmp/amazons-core.wasm core.c || exit 1
node -e "const f=require('fs'),a=f.readFileSync('/tmp/amazons-core-simd.wasm'),b=f.readFileSync('/tmp/amazons-core.wasm');f.writeFileSync('core-wasm.js','// generated by tools/build.sh from core.c — do not edit\nself.AMZ_WASM=\''+a.toString('base64')+'\';\nself.AMZ_WASM0=\''+b.toString('base64')+'\';\n');console.log('core-wasm.js', a.length, '+', b.length, 'bytes of wasm')"
clang --target=wasm32 -O3 -msimd128 -ffp-contract=off -matomics -mbulk-memory -DMT -nostdlib -fno-builtin -w -Wl,--no-entry -Wl,--export-dynamic -Wl,--shared-memory -Wl,--import-memory -Wl,--max-memory=1073741824 -o core_mt.wasm core.c || exit 1
echo "core_mt.wasm $(wc -c < core_mt.wasm) bytes"
